// Hindi for the whole app: exact English text -> Hindi, read by js/i18n.js while the Hindi switch is on.
// One entry per line, in strict JSON so scripts/i18n_extract.py and the tests can read it.
//  - "{}" in the English is a value filled in at run time (a number, a name, an amount); keep it in the Hindi. When the Hindi
//    needs another order, number them by place: {1} is the first {} of the English, {2} the second.
//  - Spaces are collapsed and a hanging separator or unclosed bracket at either end is ignored, so "· closed" is "closed".
//  - Capital letters do not matter for a whole string with no {} ("Available" also matches "available").
//  - What stands in a {} is shown as it is (a name, a number) unless it is itself a known word or phrase ("Sold", "3 days").
// Add a missing string: run `python scripts/i18n_extract.py --missing`, add a line here, re-run until nothing is missing.
// Register: plain everyday Hindi as the showroom speaks it; car-trade words in Devanagari (लीड, बुकिंग, आरटीओ);
// brand names (Classic Auto, CA Desk, WhatsApp, Telegram, Instagram, OLX, CarDekho, Exotel, Claude) stay in English letters.
