"Every car the firm holds or sells on commission. Click a row for the car file; edit price and location right in the grid.": "फ़र्म की हर गाड़ी, जो खुद की हो या कमीशन पर बिकती हो। गाड़ी की फ़ाइल के लिए लाइन दबाएँ; कीमत और जगह सीधे ग्रिड में बदलें।",
