"Leads received": "मिली लीड",
"Leads still arrive; the time left will show again in a minute.": "लीड अब भी आ रहे हैं; बचा समय एक मिनट में फिर दिखेगा।",
"Leads that came in after closing. Nobody holds them until opening; then they go out by price band and performance, a few at a time.": "बंद होने के बाद आई लीड। खुलने तक इन्हें कोई नहीं रखता; फिर ये कीमत की रेंज और परफ़ॉर्मेंस के हिसाब से थोड़ी-थोड़ी करके निकलती हैं।",
"Leads that come in after closing wait here with no salesman. At opening they go out in waves, by price band and performance.": "बंद होने के बाद आए लीड बिना सेल्समैन के यहाँ रुकते हैं। खुलने पर वे प्राइस बैंड और काम के हिसाब से बारी-बारी बँटते हैं।",
"Leads that come in after closing wait with no salesman, then go out at opening by price band and performance.": "बंद होने के बाद आई लीड बिना सेल्समैन के रुकी रहती हैं, फिर खुलने पर प्राइस बैंड और परफ़ॉर्मेंस के हिसाब से बँटती हैं।",
"Leads that go on the follow-up list unless you follow up": "वो लीड जो फ़ॉलो-अप न करने पर फ़ॉलो-अप लिस्ट में चली जाती हैं",
"Leads that go on the follow-up list unless you follow up. A call counts once its brief is filled.": "वे लीड जो फ़ॉलो-अप लिस्ट में जाएँगे, अगर आप फ़ॉलो-अप न करें। ब्रीफ़ भरने के बाद ही कॉल गिनी जाती है।",
"Leads unclaimed for longer count as missed.": "इससे ज़्यादा देर बिना उठी लीड छूटी हुई गिनी जाती है।",
"Leads waiting": "इंतज़ार में लीड",
"Leads whose salesman did not prove he called the customer back. Move each one to another salesman, keep it with a new deadline, or excuse it. Nothing moves until you approve.": "वे लीड जिनके सेल्समैन ने कस्टमर को वापस कॉल करने का सबूत नहीं दिया। हर एक को दूसरे सेल्समैन को दें, नई आख़िरी तारीख़ के साथ रखें, या छूट दें। आपके मंज़ूर करने तक कुछ नहीं बदलेगा।",
"leads with no response": "बिना जवाब की लीड",
