"Tagged lines become expenses, ledger entries, car costs and deal payments. A line goes in once, and you can take it out again from the Lines view.": "टैग हुई लाइनें खर्चा, लेजर एंट्री, गाड़ी का खर्चा और डील का पेमेंट बन जाती हैं। एक लाइन एक ही बार जाती है, और लाइनें वाले व्यू से उसे वापस निकाल सकते हैं।",
