"That inquiry has no lead yet: this one is sent on its own.": "उस इन्क्वायरी की अभी कोई लीड नहीं है: यह अलग से भेजी जाएगी।",
"That inquiry key is already used.": "यह इन्क्वायरी कोड पहले से इस्तेमाल हो चुका है।",
"That is a lot of requests in one minute. Wait a minute and try again.": "एक मिनट में बहुत सी रिक्वेस्ट हो गई हैं। एक मिनट रुकें और फिर से कोशिश करें।",
"That is not possible on this lead now.": "इस लीड पर अभी यह नहीं हो सकता।",
"That lead is closed: this makes a new lead.": "वह लीड बंद है: इससे नई लीड बनेगी।",
"That lead is not on your roll-call.": "वह लीड आपके रोल-कॉल में नहीं है।",
"That password is wrong.": "यह पासवर्ड ग़लत है।",
"That person is not in People and vendors": "यह व्यक्ति लोग और वेंडर में नहीं है",
