"That photo is too large even after shrinking. Try another.": "छोटा करने के बाद भी वह फ़ोटो बहुत बड़ी है। दूसरी आज़माएँ।",
"That photo is too large. Send a normal phone photo.": "वह फ़ोटो बहुत बड़ी है। फ़ोन की नॉर्मल फ़ोटो भेजें।",
