"That slot already has a photo. Remove it first.": "इस स्लॉट में फ़ोटो पहले से है। पहले उसे हटाएँ।",
"That staff member already has a login. Only the super-admin can add a second one.": "इस स्टाफ का लॉग इन पहले से है। दूसरा लॉग इन सिर्फ़ सुपर-एडमिन जोड़ सकता है।",
"That username is taken. Pick another.": "यह यूज़रनेम पहले से किसी का है। दूसरा चुनें।",
"That username was taken meanwhile. Say no to this request and ask for a new one.": "इस बीच यह यूज़रनेम किसी और ने ले लिया। इस रिक्वेस्ट को नामंज़ूर करें और नई रिक्वेस्ट माँगें।",
"That would make a loop: this person cannot report to someone who reports to them": "इससे चक्कर बन जाएगा: कोई उस व्यक्ति को रिपोर्ट नहीं कर सकता जो खुद उसे रिपोर्ट करता है",
"The 14-day clock from delivery": "डिलीवरी से 14 दिन की गिनती",
"The 6 digits from your authenticator app. Each code works once.": "आपके ऑथेंटिकेटर ऐप के 6 अंक। हर कोड एक ही बार चलता है।",
"The 8 must-haves first, then 2 for every mark, then the rest in shot order. At most 40 here; the full shoot goes to the Drive folder. Never photograph a paper, a screen with a name, or a chassis number.": "पहले 8 ज़रूरी फ़ोटो, फिर हर निशान की 2, फिर बाकी जिस क्रम में खींची। यहाँ ज़्यादा से ज़्यादा 40; पूरा शूट ड्राइव फ़ोल्डर में जाता है। कागज़, नाम वाली स्क्रीन या चेसिस नंबर की फ़ोटो कभी न खींचें।",
"the AI says look first · {} to look at": "एआई कहता है पहले देखें · {} देखने हैं",
"The app, and Claude for the ones it cannot read": "ऐप, और जो ऐप न पढ़ सके उनके लिए Claude",
"The app, for free": "ऐप, फ़्री में",
"The approver has": "मंज़ूर करने वाले के पास है",
"The audit log shows who looked at what, and when.": "ऑडिट लॉग में दिखता है कि किसने क्या, कब देखा।",
"The balance on the opening date; the cashbook builds on it.": "शुरुआत की तारीख का बैलेंस; कैशबुक इसी से आगे बनती है।",
"The bank account it was paid from. Leave empty for cash or on credit.": "जिस बैंक खाते से पैसा गया। कैश या उधार हो तो खाली छोड़ें।",
"The bank account the money left. Leave empty for cash.": "जिस बैंक खाते से पैसा गया। कैश हो तो खाली छोड़ें।",
"The bill reader is not installed on this server. Fill the form by hand.": "इस सर्वर पर बिल रीडर नहीं है। फ़ॉर्म हाथ से भरें।",
"The business number could not connect this call. Use your phone this time? A screenshot will be asked for.": "बिज़नेस नंबर से यह कॉल नहीं लगी। इस बार अपना फ़ोन इस्तेमाल करें? स्क्रीनशॉट माँगा जाएगा।",
"the buyer": "बायर",
"The buyer scans this with the phone camera. Google's review box for Classic Auto opens.": "बायर इसे फ़ोन के कैमरे से स्कैन करे। Classic Auto का गूगल रिव्यू बॉक्स खुल जाएगा।",
"the call desk": "कॉल डेस्क",
