"The car": "गाड़ी",
"the car": "गाड़ी",
"The car goes back to available. A refund can be recorded now.": "गाड़ी फिर से उपलब्ध हो जाएगी। रिफ़ंड अभी दर्ज कर सकते हैं।",
"The car-by-car list is for people who can open Deals. The totals above still count every delivered car.": "गाड़ी-दर-गाड़ी लिस्ट उन्हें दिखती है जो डील खोल सकते हैं। ऊपर के कुल में हर डिलीवर हुई गाड़ी गिनी गई है।",
"the cashbook, ledger, GST and TCS": "कैशबुक, लेजर, जीएसटी और टीसीएस",
"The chat with Anita and any call recording show here once the lead is yours.": "अनीता की चैट और कॉल रिकॉर्डिंग, लीड आपकी होते ही यहाँ दिखेंगी।",
"The checked screenshots could not load.": "जाँचे हुए स्क्रीनशॉट लोड नहीं हो पाए।",
"The chosen screenshot": "चुना हुआ स्क्रीनशॉट",
"The claim clock is not answering.": "लेने की घड़ी जवाब नहीं दे रही।",
"The Claude suggestions are switched off. Switch them on first (the bank narrations would be sent to Anthropic).": "Claude के सुझाव बंद हैं। पहले उन्हें चालू करें (बैंक की डिटेल Anthropic को भेजी जाएगी)।",
"The clocks run only while the showroom is open. This also moves the evening roll-call, the night queue and the call-back time customers are told.": "घड़ी सिर्फ़ शोरूम खुला होने पर चलती है। इससे शाम की हाज़िरी, रात की कतार और कस्टमर को बताया जाने वाला कॉल-बैक समय भी बदलता है।",
"The code is 6 digits.": "कोड 6 अंकों का है।",
"The daily report 30 minutes after closing, the weekly one on Monday morning, the monthly one on the last day of the month.": "रोज़ की रिपोर्ट बंद होने के 30 मिनट बाद, हफ़्ते की रिपोर्ट सोमवार सुबह, और महीने की रिपोर्ट महीने के आख़िरी दिन।",
"The dashboard only reads the lead engine's database. It never writes to it, and nothing leaves this server.": "डैशबोर्ड सिर्फ़ लीड इंजन का डेटाबेस पढ़ता है। उसमें कुछ लिखता नहीं, और कुछ भी इस सर्वर से बाहर नहीं जाता।",
"The day the money left. Leave it empty if you still owe it: it then waits under Payables instead of reaching the cashbook.": "जिस दिन पैसा गया। अगर अभी देना बाकी है तो खाली छोड़ें: तब यह कैशबुक में नहीं जाता, \"देना बाकी\" में रुका रहता है।",
"The demo has no sign-in. Use the buttons at the top to switch between owner, manager and salesman.": "डेमो में लॉग इन नहीं है। मालिक, मैनेजर और सेल्समैन बदलने के लिए ऊपर के बटन दबाएँ।",
"The draft and its photos and scans are deleted.": "ड्राफ़्ट, उसकी फ़ोटो और स्कैन हट जाएँगे।",
"The engine has not listed the bands.": "इंजन ने बैंड की लिस्ट नहीं दी।",
"The engine has not listed the salesmen.": "इंजन ने सेल्समैन की लिस्ट नहीं दी।",
"The engine name must match the name the lead engine uses, letter for letter.": "इंजन वाला नाम लीड इंजन के नाम से अक्षर-अक्षर मिलना चाहिए।",
"The file could not be read.": "फ़ाइल पढ़ी नहीं जा सकी।",
"The file has headings but no transactions. Check the dates you chose when you downloaded it.": "फ़ाइल में हेडिंग हैं पर कोई लेन-देन नहीं है। डाउनलोड करते समय जो तारीखें चुनी थीं, उन्हें देखें।",
