"{}. Profit is what is left after the car, its costs, GST on margin and the salesman's incentive.": "{}। मुनाफ़ा वह है जो गाड़ी, उसके खर्चे, मार्जिन पर जीएसटी और सेल्समैन के इंसेंटिव के बाद बचता है।",
