"{}. Score is sold × 10 + claimed × 2 − missed × 3, the same formula the lead engine uses.": "{}। स्कोर = बिकी × 10 + क्लेम × 2 − छूटी × 3, लीड इंजन भी यही फ़ॉर्मूला इस्तेमाल करता है।",
